text:
```json
[
  {
    "id": "search_returns_nothing",
    "cause": "Search indexing fails to capture photo metadata and content, leaving queries with no results.",
    "build": "Add a search diagnostics tool that shows users why a query returned nothing and suggests alternative search terms or filters.",
    "why": "Users need to understand what went wrong and have a path forward instead of hitting a dead end."
  },
  {
    "id": "library_flood",
    "cause": "Search results lack filtering and sorting options, so even successful queries return thousands of photos.",
    "build": "Build multi-faceted filters that let users narrow results by date range, location, album, person, and content type before viewing.",
    "why": "A massive result set is as useless as no results; users need to progressively refine their search."
  },
  {
    "id": "faces",
    "cause": "Face recognition groups are unstable and manual corrections are not persisted or are overwritten by re-indexing.",
    "build": "Create a locked face group feature that prevents automatic re-clustering from overwriting user-confirmed face identities.",
    "why": "Users invest time organizing faces manually and lose that work, breaking trust in the feature."
  },
  {
    "id": "memories_albums",
    "cause": "Automatic memory and album generation uses flawed date or content logic, surfacing wrong moments or deleting curated selections.",
    "build": "Let users set rules for what gets included in memories and albums, and show them a preview before auto-generation runs.",
    "why": "Users want control over what moments are highlighted and need visibility into why certain photos were chosen or removed."
  },
  {
    "id": "wrong_photo",
    "cause": "AI-powered search ranking prioritizes irrelevant results due to poor semantic understanding or over-matching.",
    "build": "Add a feedback mechanism where users can mark results as irrelevant, and show ranking confidence scores for each result.",
    "why": "Users need to correct the algorithm and understand why a photo ranked high so they can adjust their query."
  },
  {
    "id": "ask_followup",
    "cause": "The conversational search context is not maintained between queries, so follow-up questions lose the prior search scope.",
    "build": "Display the active search context and let users edit or clear it before issuing a follow-up query.",
    "why": "Users expect natural conversation flow and need to see what context is being used for their next question."
  },
  {
    "id": "document",
    "cause": "OCR and document detection are enabled by default without user consent, exposing sensitive text in search and browse.",
    "build": "Add a document sensitivity setting that lets users exclude or hide documents containing text patterns like dates, numbers, or keywords.",
    "why": "Users need control over whether sensitive documents are indexed and searchable to protect privacy."
  },
  {
    "id": "burst",
    "cause": "Burst photo selection UI is inconsistent and does not reliably show all frames or allow bulk actions.",
    "build": "Build a dedicated burst viewer that displays all frames in a grid, lets users select and delete multiple frames at once, and saves selections reliably.",
    "why": "Users need a stable, predictable way to review and manage burst sequences without losing their selections."
  },
  {
    "id": "vague_memory",
    "cause": "Search only accepts structured queries like nouns and dates, not descriptive language like colors, moods, or seasons.",
    "build": "Expand search to accept natural language descriptors like color, weather, emotion, and time-of-day, and map them to photo metadata.",
    "why": "Users often remember photos by feeling or appearance, not by exact dates or names, and need search to match how memory works."
  }
]
```
